import math

def calculate_tight_dominos(n, m):
    total = ((math.factorial(2 * n) - math.comb(2 * n, n)) // 2)

    right_sum = [(2*i + 1) for i in range(m)] + [2*(m+1)]

    left_sum = sum(j*(n-j) for j in range(n)) + sum(math.factorial(k)*math.factorial(k-1) for k in range(1, n))

    return total - sum((r//2) - l//2 for r in right_sum for l in left_sum)

